ACKNOWLEDGED = set()
def execute(adapter, command):
    if command.id not in ACKNOWLEDGED:
        adapter.send(command)
        ACKNOWLEDGED.add(command.id)

def state_is_fresh(state, now):
    age_seconds = (now - state["observed_at"]).total_seconds() if state.get("observed_at") else 0
    return age_seconds <= 300
